  'rhythm': { use: '音楽だけでなく、生活や自然の規則正しい周期にも使います。the rhythm of the seasons(季節の移り変わり)。つづり(r-h-y-t-h-m)に注意。' },
  'simply': { alt: ['(強調して)まったく、本当に ― It\'s simply wonderful.(本当にすばらしい)', '質素に ― live simply(質素に暮らす)'], ex: ['not simply A but B(単にAだけでなくBも)'] },
