  'text': { alt: ['教科書、テキスト ― a set text(指定図書)', '(講演・議論の)原文 ― the full text of the speech(演説の全文)'], use: '動詞の text は「(携帯で)メッセージを送る」です。' },
  'period': { alt: ['(授業の)時限 ― the third period(3時間目)', '(アメリカ英語で)ピリオド、終止符 ― put a period(ピリオドを打つ)', '生理(月経) ― She is on her period.(彼女は生理中だ)'] },
  'behavior': { alt: ['(機械・物質などの)動き、反応 ― the behavior of light(光のふるまい)'], use: '数えられない名詞として使うのがふつうです。動詞 behave(ふるまう)、behave yourself(行儀よくしなさい)。' },
  'misbehavior': { use: 'mis-(悪く)+behavior です。動詞 misbehave は「行儀悪くふるまう」で、特に子どもが騒ぐときによく使います。' },
