  'baggage': { use: '数えられない名詞なので a baggage、baggages とは言わず、a piece of baggage と数えます。イギリス英語では luggage がふつうです。emotional baggage は「心の重荷」です。' },
  'total': { alt: ['まったくの、完全な ― a total stranger(まったく見知らぬ人)', '合計〜になる(動詞) ― The cost totaled $100.(費用は合計100ドルになった)'], ex: ['in total(全部で)'] },
