  'level': { alt: ['平らな、同じ高さの(形容詞) ― level ground(平らな地面)', '(建物を)取り壊す、平らにする(動詞) ― level the building(建物を取り壊す)'], ex: ['on the level(正直な)'] },
  'studio': { alt: ['(ワンルームの)小さな部屋 ― a studio apartment(ワンルームマンション)', '(映画などの)制作会社 ― a Hollywood studio(ハリウッドの映画会社)'] },
  'throat': { use: 'have a sore throat(のどが痛い)の形でよく使います。clear my throat(せき払いする)、at each other\'s throats(激しくけんかして)。' },
